SELECT *
FROM `bidata-sharedus-production.S2.snp_RPP_Portfolio_Monthly`
WHERE SnapshotDate BETWEEN DATE '2023-01-01' AND DATE '2025-05-01';

with TMX_SA_item_service_line as (
    SELECT 'TMX_SA_item_service_line' as table_name,count(*) as count FROM S0_TMX.tmx_sa_item_service_line
),TMX_WO_item_YN_attributes as (
	SELECT 'TMX_WO_item_YN_attributes' as table_name,count(*) as count FROM S0_TMX.tmx_wo_item_yn_attributes
), final_count as (
	SELECT * FROM TMX_SA_item_service_line
	UNION ALL
	SELECT * FROM TMX_WO_item_YN_attributes
)
SELECT * from final_count
